import { loadFont as loadExo } from "@remotion/google-fonts/Exo2";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// CONCRETAR Construtora e Incorporadora (cliente "Souza Concretar"). Vitrine vertical de 34,6 s sobre a locução
// (ElevenLabs, voz o locutor, 32,5 s, entra em LEAD). Copy do cliente (texto que veio pelo WhatsApp) + Petrolina e o
// pedido de seguir o perfil e chamar no número. Identidade do logo: grafite quase preto, laranja das barras, prata do
// letreiro; letra itálica pesada (Exo 2) como o "CONCRETAR", e as duas barras "//" como marca de destaque.
// Tempos = tempo da palavra na voz (edit/transcripts/voz-v1.json em (arquivo do cliente)).
// O áudio é mixado fora (tools/mix_souza.py): aqui o vídeo é mudo.

const { fontFamily: F } = loadExo("italic", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const SZ_FPS = 30;
const LEAD = 0.25;
export const SZ_FRAMES = Math.round(34.6 * SZ_FPS);

const INK = "#0E0E10";
const CHAR = "#1B1C1F";
const ORANGE = "#ED771D";
const SILVER = "#D9DCE1";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const sp = (t: number, a: number, damping = 13, stiffness = 210) =>
  spring({ frame: Math.round((t - a) * SZ_FPS), fps: SZ_FPS, config: { damping, stiffness } });
const fr = (s: number) => Math.round((s + LEAD) * SZ_FPS);

// texto: entra desfocado subindo um pouco, assenta e fica parado
const entra = (t: number, at: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: Math.min(1, e * 1.6), filter: `blur(${((1 - e) * 12).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 24).toFixed(1)}px)` };
};

// ───────── fundo: foto ou trecho do tour em tela cheia, câmera sempre andando ─────────
type Entrada = "corte" | "barra" | "zoom" | "fade" | "empurra";
type Cam = { z?: [number, number]; x?: [number, number]; y?: [number, number]; pos?: string };

// a entrada de cada plano; "barra" = faixa laranja inclinada (as "//" do logo) varrendo a tela e revelando o plano
const useEntrada = (t: number, a: number, tipo: Entrada) => {
  const d = tipo === "fade" ? 0.55 : tipo === "barra" ? 0.5 : 0.4;
  const e = io(t, a, a + d);
  let style: React.CSSProperties = {};
  if (tipo === "fade") style = { opacity: e };
  if (tipo === "zoom") style = { opacity: Math.min(1, e * 2.2), transform: `scale(${(1 + 0.22 * (1 - e)).toFixed(4)})`, filter: `blur(${((1 - e) * 16).toFixed(1)}px)` };
  if (tipo === "empurra") style = { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)` };
  if (tipo === "barra") {
    // diagonal: o plano novo aparece da esquerda para a direita, por trás da faixa
    const x = -500 + e * 2100;
    style = { clipPath: `polygon(0 0, ${x + 300}px 0, ${x - 300}px 1920px, 0 1920px)` };
  }
  return { e, style };
};

const Barra: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  if (t < a - 0.02 || t > a + 0.6) return null;
  const e = io(t, a, a + 0.5);
  const x = -500 + e * 2100;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div style={{ position: "absolute", top: -200, height: 2320, left: x - 330, width: 64, background: ORANGE, transform: "skewX(-17.3deg)", transformOrigin: "50% 50%", boxShadow: `0 0 50px ${ORANGE}88` }} />
      <div style={{ position: "absolute", top: -200, height: 2320, left: x - 230, width: 64, background: ORANGE, transform: "skewX(-17.3deg)", transformOrigin: "50% 50%", boxShadow: `0 0 50px ${ORANGE}88` }} />
    </AbsoluteFill>
  );
};

const Escurece: React.FC<{ topo?: boolean }> = ({ topo }) => (
  <>
    <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,14,16,0) 42%, rgba(14,14,16,0.7) 66%, rgba(14,14,16,0.94) 100%)" }} />
    {topo && <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,14,16,0.55) 0%, rgba(14,14,16,0) 22%)" }} />}
  </>
);

const Foto: React.FC<{ t: number; src: string; a: number; b: number; tipo?: Entrada; cam?: Cam; sombra?: boolean }> = ({ t, src, a, b, tipo = "corte", cam = {}, sombra = true }) => {
  const { e, style } = useEntrada(t, a, tipo);
  if (t < a - 0.02 || t > b + 0.7) return null;
  const { z = [1.06, 1.16], x = [0, 0], y = [0, 0], pos = "center" } = cam;
  const p = lin(t, a, b + 0.5);
  const s = z[0] + (z[1] - z[0]) * p;
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK, ...style }}>
      <Img src={staticFile(`souza/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `translate(${(x[0] + (x[1] - x[0]) * p).toFixed(2)}%, ${(y[0] + (y[1] - y[0]) * p).toFixed(2)}%) scale(${s.toFixed(4)})` }} />
      {sombra && <Escurece />}
      {e < 0 && null}
    </AbsoluteFill>
  );
};

// trecho do tour (vídeo do cliente). Escala mínima 1,24 para tirar a marca do CapCut dos cantos.
const Tour: React.FC<{ t: number; a: number; b: number; start: number; tipo?: Entrada; z?: [number, number]; ox?: number; oy?: number; dx?: [number, number] }> = ({ t, a, b, start, tipo = "corte", z = [1.26, 1.36], ox = 50, oy = 50, dx = [0, 0] }) => {
  const { style } = useEntrada(t, a, tipo);
  if (t < a - 0.02 || t > b + 0.7) return null;
  const p = lin(t, a, b + 0.5);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK, ...style }}>
      <Sequence from={fr(a)} layout="none">
        <AbsoluteFill style={{ transform: `translateX(${(dx[0] + (dx[1] - dx[0]) * p).toFixed(1)}px) scale(${(z[0] + (z[1] - z[0]) * p).toFixed(4)})`, transformOrigin: `${ox}% ${oy}%` }}>
          <OffthreadVideo muted src={staticFile("souza/tour.mp4")} trimBefore={Math.round(start * SZ_FPS)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        </AbsoluteFill>
      </Sequence>
      <Escurece />
    </AbsoluteFill>
  );
};

// ───────── lettering: sempre no mesmo lugar, na parte de baixo ─────────
const Barras: React.FC<{ size?: number; cor?: string }> = ({ size = 40, cor = ORANGE }) => (
  <svg width={size * 0.95} height={size} viewBox="0 0 38 40" style={{ display: "block", flex: "none" }}>
    <path d="M12 0 H22 L10 40 H0 Z" fill={cor} />
    <path d="M28 0 H38 L26 40 H16 Z" fill={cor} />
  </svg>
);

// linha de cima: "//" + texto prata em caixa alta
const Olho: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number }> = ({ t, at, children, size = 50 }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 18, ...entra(t, at) }}>
    <Barras size={size * 0.78} />
    <div style={{ fontFamily: F, fontWeight: 800, fontStyle: "italic", fontSize: size, letterSpacing: "0.04em", textTransform: "uppercase", color: SILVER, whiteSpace: "nowrap", textShadow: "0 3px 20px rgba(0,0,0,0.6)" }}>{children}</div>
  </div>
);

// palavra-chave num bloco laranja inclinado, como as barras do logo
const Destaque: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; cor?: string; tinta?: string }> = ({ t, at, children, size = 100, cor = ORANGE, tinta = WHITE }) => {
  const s = sp(t, at);
  const w = k(t, at, 0.35);
  return (
    <div style={{ position: "relative", display: "inline-block", opacity: Math.min(1, s * 3), transform: `scale(${(0.7 + 0.3 * s).toFixed(4)})` }}>
      <div style={{ position: "absolute", inset: `0 ${-size * 0.12}px`, background: cor, transform: `skewX(-14deg) scaleX(${w.toFixed(4)})`, transformOrigin: "0% 50%", borderRadius: 6, boxShadow: `0 18px 50px ${cor}55` }} />
      <div style={{ position: "relative", padding: `${size * 0.02}px ${size * 0.22}px ${size * 0.08}px`, fontFamily: F, fontWeight: 900, fontStyle: "italic", fontSize: size, lineHeight: 1.08, letterSpacing: "-0.01em", color: tinta, whiteSpace: "nowrap" }}>{children}</div>
    </div>
  );
};

const Grande: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; cor?: string }> = ({ t, at, children, size = 104, cor = WHITE }) => (
  <div style={{ fontFamily: F, fontWeight: 900, fontStyle: "italic", fontSize: size, lineHeight: 1.04, letterSpacing: "-0.01em", color: cor, whiteSpace: "nowrap", textShadow: "0 4px 30px rgba(0,0,0,0.5)", ...entra(t, at) }}>{children}</div>
);

// bloco centralizado na parte de baixo; some inteiro (rápido) antes do próximo entrar
const Bloco: React.FC<{ t: number; a: number; b: number; bottom?: number; gap?: number; children: React.ReactNode }> = ({ t, a, b, bottom = 330, gap = 22, children }) => {
  if (t < a - 0.05 || t > b + 0.14) return null;
  const o = k(t, b, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, bottom, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `translateY(${(-o * 20).toFixed(1)}px)` }}>{children}</div>
  );
};

// ───────── ícones (traço prata, detalhe laranja) ─────────
const Check: React.FC<{ t: number; at: number; size?: number }> = ({ t, at, size = 92 }) => {
  const c = k(t, at, 0.4);
  const v = k(t, at + 0.15, 0.3);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: "block" }}>
      <circle cx="50" cy="50" r="44" fill={ORANGE} opacity={c} />
      <path d="M29 52 L44 66 L72 36" fill="none" stroke={WHITE} strokeWidth="10" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="64" strokeDashoffset={64 * (1 - v)} />
    </svg>
  );
};

const Pin: React.FC<{ size?: number }> = ({ size = 90 }) => (
  <svg width={size * 0.75} height={size} viewBox="0 0 24 32" style={{ display: "block" }}>
    <path d="M12 0C5.4 0 0 5.2 0 11.7 0 20.5 12 32 12 32s12-11.5 12-20.3C24 5.2 18.6 0 12 0z" fill={ORANGE} />
    <circle cx="12" cy="11.5" r="4.6" fill={INK} />
  </svg>
);

const Balao: React.FC<{ size?: number }> = ({ size = 96 }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: "block" }}>
    <path d="M18 18 H82 a10 10 0 0 1 10 10 V62 a10 10 0 0 1 -10 10 H44 L26 88 V72 H18 a10 10 0 0 1 -10 -10 V28 a10 10 0 0 1 10 -10z" fill={ORANGE} />
    <circle cx="32" cy="45" r="6" fill={WHITE} /><circle cx="50" cy="45" r="6" fill={WHITE} /><circle cx="68" cy="45" r="6" fill={WHITE} />
  </svg>
);

const Agenda: React.FC<{ t: number; at: number; size?: number }> = ({ t, at, size = 96 }) => {
  const v = k(t, at, 0.35);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: "block" }}>
      <rect x="10" y="18" width="80" height="72" rx="10" fill={CHAR} stroke={SILVER} strokeWidth="6" />
      <rect x="10" y="18" width="80" height="20" rx="8" fill={ORANGE} />
      <rect x="28" y="8" width="8" height="18" rx="4" fill={SILVER} /><rect x="64" y="8" width="8" height="18" rx="4" fill={SILVER} />
      <path d="M34 62 L46 74 L68 50" fill="none" stroke={ORANGE} strokeWidth="9" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="50" strokeDashoffset={50 * (1 - v)} />
    </svg>
  );
};

const Insta: React.FC<{ size?: number; cor?: string }> = ({ size = 56, cor = WHITE }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ display: "block" }}>
    <rect x="2.5" y="2.5" width="19" height="19" rx="5.5" fill="none" stroke={cor} strokeWidth="2.2" />
    <circle cx="12" cy="12" r="4.3" fill="none" stroke={cor} strokeWidth="2.2" />
    <circle cx="17.4" cy="6.6" r="1.3" fill={cor} />
  </svg>
);

const Fone: React.FC<{ size?: number; cor?: string }> = ({ size = 56, cor = WHITE }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ display: "block" }}>
    <path fill={cor} d="M6.6 10.8a15.1 15.1 0 0 0 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1A17 17 0 0 1 3 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1z" />
  </svg>
);

// ───────── cenas desenhadas ─────────

// "Aqui na Concretar": a casa pronta ao fundo, escura e desfocada, e o logo entrando grande
const Marca: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const { style } = useEntrada(t, a, "zoom");
  if (t < a - 0.02 || t > b + 0.7) return null;
  const p = lin(t, a, b + 0.5);
  const s = sp(t, 6.0, 15, 160);
  const brilho = lin(t, 6.5, 7.3);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK, ...style }}>
      <Img src={staticFile("souza/foto-2.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "blur(14px) brightness(0.32)", transform: `scale(${(1.25 - 0.1 * p).toFixed(4)})` }} />
      <AbsoluteFill style={{ background: "radial-gradient(60% 40% at 50% 46%, rgba(237,119,29,0.16) 0%, rgba(14,14,16,0) 70%)" }} />
      <div style={{ position: "absolute", left: 120, right: 120, top: 640, display: "flex", flexDirection: "column", alignItems: "center", transform: `scale(${(1 + 0.06 * p).toFixed(4)})` }}>
        <div style={{ position: "relative", opacity: Math.min(1, s * 2.5), transform: `scale(${(0.6 + 0.4 * s).toFixed(4)})`, filter: `blur(${((1 - Math.min(1, s)) * 10).toFixed(1)}px)` }}>
          <Img src={staticFile("souza/logo.png")} style={{ width: 840, display: "block" }} />
          {/* reflexo passando no logo */}
          <div style={{ position: "absolute", inset: 0, overflow: "hidden", WebkitMaskImage: `url(${staticFile("souza/logo.png")})`, WebkitMaskSize: "100% 100%", maskImage: `url(${staticFile("souza/logo.png")})`, maskSize: "100% 100%" }}>
            <div style={{ position: "absolute", top: -100, bottom: -100, width: 160, left: -200 + brilho * 1240, background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.75) 50%, rgba(255,255,255,0) 100%)", transform: "skewX(-17deg)" }} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// "atendemos em todas as cidades próximas": Petrolina no centro e a região se acendendo em volta
const PONTOS: [number, number, number][] = [[-300, -250, 19.35], [290, -300, 19.55], [-350, 140, 19.75], [330, 180, 19.95], [-90, 380, 20.15], [120, -420, 20.35]];
const Regiao: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const { style } = useEntrada(t, a, "fade");
  if (t < a - 0.02 || t > b + 0.7) return null;
  const p = lin(t, a, b + 0.5);
  const CX = 540, CY = 760;
  const pin = sp(t, a + 0.05, 12, 200);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: `radial-gradient(70% 45% at 50% 40%, ${CHAR} 0%, ${INK} 100%)`, ...style }}>
      <AbsoluteFill style={{ transform: `scale(${(1.0 + 0.12 * p).toFixed(4)}) rotate(${(-2 + 3 * p).toFixed(3)}deg)`, transformOrigin: `${CX}px ${CY}px` }}>
        <svg width="1080" height="1920" style={{ position: "absolute", inset: 0 }}>
          {[160, 300, 440].map((r, i) => <circle key={i} cx={CX} cy={CY} r={r} fill="none" stroke={SILVER} strokeOpacity={0.09} strokeWidth="2" />)}
          {[0, 0.6, 1.2].map((d, i) => {
            const r = ((t - a - d) % 1.8 + 1.8) % 1.8 / 1.8;
            return t > a + d ? <circle key={`o${i}`} cx={CX} cy={CY} r={40 + 420 * r} fill="none" stroke={ORANGE} strokeWidth={5 - 3 * r} opacity={0.6 * (1 - r)} /> : null;
          })}
          {PONTOS.map(([dx, dy, at], i) => {
            const g = io(t, at - 0.25, at + 0.2);
            const d = k(t, at + 0.1, 0.35);
            return (
              <g key={i}>
                <line x1={CX} y1={CY} x2={CX + dx * g} y2={CY + dy * g} stroke={ORANGE} strokeWidth="4" strokeDasharray="6 14" strokeLinecap="round" opacity={0.8} />
                <circle cx={CX + dx} cy={CY + dy} r={20 * d} fill={SILVER} />
                <circle cx={CX + dx} cy={CY + dy} r={8 * d} fill={ORANGE} />
              </g>
            );
          })}
        </svg>
        <div style={{ position: "absolute", left: CX - 60, top: CY - 150, width: 120, display: "flex", justifyContent: "center", opacity: Math.min(1, pin * 3), transform: `translateY(${((1 - pin) * -80).toFixed(1)}px)` }}>
          <Pin size={150} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// final: casa ao fundo escurecida, logo, perfil e número
const Final: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  const { style } = useEntrada(t, a, "zoom");
  if (t < a - 0.02) return null;
  const p = lin(t, a, 34.4);
  const pulso = 1 + 0.06 * Math.sin(lin(t, 31.82, 32.42) * Math.PI);
  const s1 = sp(t, 29.6), s2 = sp(t, 31.2);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK, ...style }}>
      <Img src={staticFile("souza/foto-3.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "brightness(0.34) blur(3px)", transform: `scale(${(1.1 + 0.34 * p).toFixed(4)}) translate(${(-2 + 4 * p).toFixed(2)}%, ${(-3 + 6 * p).toFixed(2)}%)` }} />
      <AbsoluteFill style={{ background: "radial-gradient(70% 45% at 50% 30%, rgba(237,119,29,0.13) 0%, rgba(14,14,16,0) 70%)" }} />
      <div style={{ position: "absolute", left: 120, right: 120, top: 330, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <Img src={staticFile("souza/logo.png")} style={{ width: 760, ...entra(t, a + 0.05, 0.6) }} />
        <div style={{ marginTop: 110, display: "flex", alignItems: "center", gap: 22, background: ORANGE, borderRadius: 999, padding: "24px 48px 26px", boxShadow: `0 22px 60px ${ORANGE}55`, opacity: Math.min(1, s1 * 3), transform: `scale(${(0.7 + 0.3 * s1).toFixed(4)})` }}>
          <Insta size={60} />
          <div style={{ fontFamily: F, fontWeight: 800, fontStyle: "italic", fontSize: 54, color: WHITE, whiteSpace: "nowrap" }}>@suamarca</div>
        </div>
        <div style={{ marginTop: 34, display: "flex", alignItems: "center", gap: 22, background: "rgba(27,28,31,0.92)", border: `3px solid ${SILVER}55`, borderRadius: 999, padding: "22px 48px 24px", opacity: Math.min(1, s2 * 3), transform: `scale(${((0.7 + 0.3 * s2) * pulso).toFixed(4)})` }}>
          <Fone size={58} cor={ORANGE} />
          <div style={{ fontFamily: F, fontWeight: 900, fontStyle: "italic", fontSize: 76, color: WHITE, whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}>(00) 00000-0000</div>
        </div>
        <div style={{ marginTop: 50, display: "flex", alignItems: "center", gap: 16, ...entra(t, 32.0) }}>
          <Barras size={34} />
          <div style={{ fontFamily: F, fontWeight: 800, fontStyle: "italic", fontSize: 42, letterSpacing: "0.04em", textTransform: "uppercase", color: SILVER, whiteSpace: "nowrap" }}>Petrolina-PE e região</div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── vídeo ─────────
export const SouzaConcretar: React.FC = () => {
  const t = useCurrentFrame() / SZ_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: INK }}>
      {/* "Procurando uma construtora que realmente te escute..." */}
      <Foto t={t} src="foto-3.jpg" a={-LEAD} b={3.3} cam={{ z: [1.32, 1.08], y: [2, -1] }} />
      {/* "...e acompanhe sua obra do início ao fim?" obra → casa pronta */}
      <Foto t={t} src="foto-7.jpg" a={3.3} b={4.85} tipo="barra" cam={{ z: [1.08, 1.2], y: [-2, 1] }} />
      <Foto t={t} src="foto-2.jpg" a={4.85} b={5.95} tipo="zoom" cam={{ z: [1.04, 1.14], x: [1, -1] }} />
      {/* "Aqui na Concretar" */}
      <Marca t={t} a={5.95} b={7.35} />
      {/* "nosso compromisso vai além do projeto" */}
      <Foto t={t} src="foto-9.jpg" a={7.35} b={9.85} tipo="empurra" cam={{ z: [1.08, 1.34], x: [-3, 3], y: [1.5, -1.5] }} />
      {/* "entregamos transparência, prazos cumpridos e um atendimento personalizado em cada detalhe" */}
      <Tour t={t} a={9.85} b={11.5} start={3.0} tipo="barra" z={[1.26, 1.38]} />
      <Tour t={t} a={11.5} b={12.95} start={6.6} tipo="fade" z={[1.3, 1.26]} dx={[30, -30]} />
      <Tour t={t} a={12.95} b={16.4} start={12.6} tipo="zoom" z={[1.26, 1.4]} oy={40} />
